/* ============================================================
   O PAPEL TIMBRADO DA ESCOLA

   POR QUE O LOGO ESTÁ AQUI DENTRO, EM TEXTO
   O documento é montado no servidor e impresso pelo navegador. Se o
   timbre apontasse para /ibau-capelo.webp, o logo dependeria de mais uma
   ida à rede acontecer ANTES de o diálogo de impressão abrir — e quando
   não acontece, sai um PDF sem marca nenhuma, que é justamente o defeito
   que estou consertando. Embutido, o logo já está na página no instante
   em que ela existe. Não tem corrida para perder.

   São 20 KB de imagem (26 KB depois de virar texto), gerados a partir de
   public/ibau-capelo.webp reduzido para 300px de largura — que em 26 mm
   de papel dá cerca de 290 pontos por polegada, nítido na impressão e
   sem carregar um arquivo de 84 KB para desenhar um selo pequeno.

   POR QUE ISTO É UM ARQUIVO SEPARADO
   Antes cada documento carregava o próprio timbre em HTML solto. Já eram
   dois (chamada em papel e planilha), e o terceiro seria o boletim. Três
   cópias do mesmo cabeçalho é a garantia de que um dia dois documentos da
   mesma escola vão sair com identidades diferentes.

   POR QUE NÃO É UM PDF DE VERDADE
   HTML com folha de estilo de impressão sai igual em qualquer navegador
   ("Salvar como PDF" é nativo), pesa pouco, e mudar o timbre depois é
   editar texto — não recompilar um gerador de PDF binário.
   ============================================================ */

/** O selo da Escola de Líderes, embutido para nunca faltar no papel. */
export const MARCA_DO_DOCUMENTO =
  'data:image/png;base64,'

/** Escapa texto que veio do banco antes de virar HTML. */
export function esc(t: string | null | undefined): string {
  return String(t ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

/**
 * A folha de estilo de todos os documentos da escola.
 *
 * Verde da marca (#0f664a / #12805a), A4, e a regra de impressão que some
 * com os botões de tela. Quem for criar um documento novo herda tudo isto
 * e só escreve o miolo.
 */
/* ============================================================
   AS CALIGRAFIAS, EMBUTIDAS TAMBÉM

   Este erro só apareceu quando eu olhei o boletim pronto: a assinatura
   saía em Times New Roman. O nome da fonte estava certo no estilo, mas a
   fonte em si vive dentro do site — e o documento é uma página avulsa,
   sem nada do site carregado. O navegador pedia 'Great Vibes', não achava,
   e caía na fonte padrão. Uma assinatura em letra de forma não assina
   nada: parece exatamente o que é, um texto qualquer.

   São 42 KB e 24 KB de fonte (57 KB e 31 KB depois de virar texto). Pesa,
   e é o preço de o documento ser autossuficiente — ele sai igual no
   computador da secretaria, no celular de quem recebe, e impresso.
   ============================================================ */
const FONTES_DA_ASSINATURA = `
@font-face {
  font-family: 'Great Vibes';
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,) format('woff2');
}
@font-face {
  font-family: 'Dancing Script';
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,) format('woff2');
}
`

export const ESTILO_DO_DOCUMENTO = `
${FONTES_DA_ASSINATURA}
  @page { size: A4; margin: 16mm 14mm; }
  * { box-sizing: border-box; }
  body {
    font-family: 'Segoe UI', system-ui, -apple-system, Arial, sans-serif;
    color: #12211b; margin: 0; font-size: 11.5pt;
  }

  /* ---------- Papel timbrado ---------- */
  .timbre {
    display: flex; align-items: center; gap: 14px;
    border-bottom: 2.5px solid #12805a; padding-bottom: 12px; margin-bottom: 6px;
  }
  .timbre .marca { display: flex; align-items: center; gap: 12px; }
  .timbre .marca img { width: 46px; height: auto; flex: 0 0 auto; }
  .timbre h1 { font-size: 15pt; margin: 0; letter-spacing: -0.2px; }
  .timbre .sub { font-size: 9pt; color: #4a6157; margin-top: 2px; letter-spacing: .4px; }
  .timbre .dir { margin-left: auto; text-align: right; font-size: 8.5pt; color: #6b7f76; }

  h2 { font-size: 13pt; margin: 16px 0 10px; }

  /* ---------- Bloco de dados ---------- */
  .info {
    display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px 22px;
    background: #f4faf7; border: 1px solid #d8ece3; border-radius: 6px;
    padding: 10px 13px; margin-bottom: 16px; font-size: 10pt;
  }
  .info b { color: #0f664a; font-weight: 600; }

  /* ---------- Tabela ---------- */
  table { width: 100%; border-collapse: collapse; }
  th {
    background: #0f664a; color: #fff; font-size: 9.5pt; font-weight: 600;
    text-align: left; padding: 7px 9px; letter-spacing: .3px;
  }
  td { padding: 7px 9px; border-bottom: 1px solid #e3ece8; font-size: 10.5pt; }
  tr:nth-child(even) td { background: #fafcfb; }
  .num { width: 34px; color: #6b7f76; text-align: center; }
  .n { text-align: right; font-variant-numeric: tabular-nums; }

  /* ---------- Rodapé ---------- */
  .resumo {
    margin-top: 14px; display: flex; gap: 26px; flex-wrap: wrap; font-size: 10pt;
    border-top: 1.5px solid #d8ece3; padding-top: 10px;
  }
  .resumo b { color: #0f664a; }
  .assinatura {
    margin-top: 46px; display: flex; justify-content: space-around;
    text-align: center; font-size: 9.5pt; color: #4a6157;
  }
  .assinatura div { border-top: 1px solid #9aada5; padding-top: 5px; width: 210px; }
  .rodape {
    position: fixed; bottom: 0; left: 0; right: 0;
    font-size: 8pt; color: #8fa39a; text-align: center;
  }
  /* ---------- Assinatura eletrônica no papel ---------- */
  .assinatura-eletronica { margin-top: 26px; display: inline-block; min-width: 300px; }
  .ae-nome { color: #0f2f24; line-height: 1.15; white-space: nowrap; }
  .ae-linha { border-top: 1px solid #9aada5; padding-top: 5px; font-size: 9.5pt; color: #4a6157; }
  .ae-rodape { margin-top: 5px; font-size: 8pt; color: #7d908a; }

  @media print { .noprint { display: none !important; } }
  /* O botão ficava em cima do canto direito do timbre e escondia o texto
     dele. No papel não aparece (é .noprint), mas na tela cobria — e a tela
     é onde a pessoa confere se o documento saiu certo. Foi para baixo. */
  .noprint { position: fixed; bottom: 16px; right: 16px; display: flex; gap: 8px; z-index: 5; }
  .noprint button { box-shadow: 0 6px 20px rgba(15,102,74,.28); }
  .noprint button {
    font: inherit; font-size: 10pt; padding: 8px 14px; border-radius: 8px;
    border: 0; cursor: pointer; background: #12805a; color: #fff; font-weight: 600;
  }
`

/** O cabeçalho com o selo. Todo documento da escola começa por ele. */
export function timbre(canto = 'Documento gerado pela plataforma<br>Escola de Líderes IBAU'): string {
  return `
  <header class="timbre">
    <div class="marca">
      <img src="${MARCA_DO_DOCUMENTO}" alt="Escola de Líderes IBAU">
      <div>
        <h1>Igreja Batista do Avivamento</h1>
        <div class="sub">ESCOLA DE LÍDERES IBAU</div>
      </div>
    </div>
    <div class="dir">${canto}</div>
  </header>`
}

/**
 * Monta a página inteira do documento.
 *
 * O diálogo de impressão só abre depois que o navegador termina de
 * carregar a página (evento `load`, que já espera as imagens) mais uma
 * folga curta. Sem essa folga o Chrome às vezes abre a impressão com o
 * desenho pela metade.
 */
export function paginaDeDocumento(opcoes: {
  titulo: string
  canto?: string
  corpo: string
  imprimirSozinho?: boolean
}): string {
  const { titulo, canto, corpo, imprimirSozinho = true } = opcoes
  return `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(titulo)}</title>
<style>${ESTILO_DO_DOCUMENTO}</style>
</head>
<body>
  <div class="noprint"><button onclick="window.print()">Imprimir / Salvar PDF</button></div>
  ${timbre(canto)}
  ${corpo}
  <div class="rodape">Escola de Líderes IBAU — Igreja Batista do Avivamento</div>
${imprimirSozinho ? '  <script>window.addEventListener("load", () => setTimeout(() => window.print(), 500))</script>' : ''}
</body>
</html>`
}
